<script setup>
import { ref, computed, onMounted } from 'vue'
import { Store, Wallet, UsersRound, ArrowUpRight, ShieldCheck } from 'lucide-vue-next'
import { api } from '../api'
import { money, initials } from '../utils/format'
import StatCard from '../components/StatCard.vue'
import PaymentTable from '../components/PaymentTable.vue'
const data=ref(null),error=ref(''),loading=ref(true),selected=ref(''), limit=ref(12)
async function load(){loading.value=true;error.value='';try{data.value=await api.admin()}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
const total=computed(()=>data.value?.payments.filter(p=>p.status==='success').reduce((s,p)=>s+p.amount,0)||0)
const employees=computed(()=>data.value?.employees.filter(e=>!selected.value||e.merchantId===selected.value)||[])
const payments=computed(()=>[...(data.value?.payments||[])].filter(p=>!selected.value||p.merchantId===selected.value).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)))
const name=id=>data.value?.employees.find(e=>e.id===id)?.name||'Сотрудник'
</script>
<template><div class="page-heading"><div><h1>Обзор платформы</h1><p>Статистика всех ресторанов, сотрудников и платежей.</p></div><span class="demo-pill"><ShieldCheck :size="15"/>Администратор платформы</span></div><div v-if="loading" class="page-loading"><span class="spinner"></span>Загрузка платформы…</div><div v-else-if="error" class="error-banner">{{ error }}<button class="btn" @click="load">Повторить</button></div><template v-else-if="data"><div class="stats-grid admin-stats"><StatCard label="Рестораны" :value="data.merchants.length" note="Зарегистрированы на платформе" :icon="Store"/><StatCard label="Чаевые платформы" :value="money(total)" note="Успешные платежи за всё время" :icon="Wallet" accent/><StatCard label="Сотрудники" :value="data.employees.length" note="Сотрудники всех ресторанов" :icon="UsersRound"/></div><section class="panel"><div class="panel-heading"><div><h2>Рестораны</h2><p>Выберите ресторан, чтобы посмотреть его данные</p></div><button class="text-link" @click="selected=''">Вся платформа</button></div><div class="merchant-list"><button v-for="m in data.merchants" :key="m.id" :class="{selected:selected===m.id}" @click="selected=m.id"><span class="avatar sage">{{ initials(m.name) }}</span><span><strong>{{ m.name }}</strong><small>{{ m.email }}</small></span><span class="merchant-location">{{ m.location }}</span><ArrowUpRight :size="19"/></button></div></section><div class="admin-details"><section class="panel"><div class="panel-heading"><h2>Сотрудники <span class="muted">{{ employees.length }}</span></h2></div><div v-if="!employees.length" class="empty">Сотрудники пока не добавлены</div><div v-for="e in employees" :key="e.id" class="admin-employee"><span class="avatar small" :class="e.color">{{ initials(e.name) }}</span><div><strong>{{ e.name }}</strong><small>{{ e.role }}</small></div><span class="status" :class="e.active?'success':'cancelled'">{{ e.active?'Активен':'Неактивен' }}</span></div></section><section class="panel"><div class="panel-heading"><h2>Платежи <span class="muted">{{ payments.length }}</span></h2></div><PaymentTable :payments="payments.slice(0,limit)" :employee-name="name"/><div v-if="payments.length>limit" class="pagination"><span>Показано {{ limit }} из {{ payments.length }}</span><button class="text-link" @click="limit+=12">Показать ещё</button></div></section></div></template></template>
